import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易集注 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易集注 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"zh/classics/jizhu/030.md","filePath":"zh/classics/jizhu/030.md"}'),l={name:"zh/classics/jizhu/030.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>大者阳也，其卦干下艮上，以阳畜阳，所以畜之力大，非如巽以阴畜阳，所畜之力小，故曰大畜。又有蕴畜之义，又有畜止之义。《序卦》：“有无妄，然后可畜，故受之以大畜，所以次无妄。”</p><p>中爻兑口在外，四近于五之君，当食禄于朝，不家食之象也。何以言食?本卦大象离，故《彖》辞曰“辉光日新”者，因大象离也。离错坎，又象颐，有饮食自养之象。因错坎水，中爻震木，所以有涉大川之象。又本卦错萃，萃大象坎。若以卦体论，四五中空，有舟象。乾健应四五上进，有舟行而前之象。应乎天者，以卦德论其理也，彖辞爻辞皆各取义不同。贞者正也，利于正道，如多识前言往行，以畜其德是也。吉者，吾道之大行也。言所蕴畜者皆正，则畜极而通，当食禄于朝，大有作为，以济天下之险也。</p><p>《彖》曰：大畜，刚健笃实，辉光日新其德，刚上而尚贤。能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。</p><p>以卦德、卦综、卦体释卦名、卦辞。刚健者，内而存主也。笃实者，外而践履也。刚健无一毫人欲之阴私，笃实无一毫人欲之虚假，则暗然日章，光辉宣著，其德自日新又新，所以积小高大，以成其畜也。名大畜者以此。刚健乾象，笃实艮象，二体相合离象，故又言辉光日新。刚上者，大畜综无妄，无妄下卦之震上而为大畜之艮也，上而为艮，则阳刚之贤在上矣，是尚其贤也。止健者，止居上，而健居下，禁民之强暴也，此二者，皆大正之事，所以利贞，若以止健为止阳刚君子，则又非大正矣。养贤者，食禄以养贤也。应天者，下应乎干也。天者时而已矣，既负蕴畜之才，又有乾健之力，所以当乘时而出，以济天下之险难也。惟刚上，则贤人在上，故能尚贤，故能成艮而止健，故能兑口在外卦，而食禄于外。故能六五得中，而应乎干。此四者，皆卦综刚上之功也。</p><h3 id="《象》曰-天在山中-大畜-君子以多识前言往行-以畜其德。" tabindex="-1">《象》曰：天在山中，大畜，君子以多识前言往行，以畜其德。 <a class="header-anchor" href="#《象》曰-天在山中-大畜-君子以多识前言往行-以畜其德。" aria-label="Permalink to “《象》曰：天在山中，大畜，君子以多识前言往行，以畜其德。”">​</a></h3><p>天者一气而已，气贯乎地中，天依乎地，地附乎天，云雷皆自地出。故凡地下空处、深处皆是天，故曰天在山中。多识，即大畜之意，乃知之功夫也。古圣贤之嘉言善行，皆理之所在，皆古人之德也。君子多识之，考迹以观其用，察言以求其心，则万理会通于我，而我之德大矣，此君子体大畜之功也。中爻震，足行之象。兑口，言之象。</p><p>初九，有厉，利已。(已，夷止反。)</p><p>干三阳为艮所畜，故内外之卦，各具其义。内卦受畜，以自止为义。以阴阳论，若君子受畜于小人也。外卦能畜，以止人为义。以上下论，若在位之禁止强暴也。易主于变易，所以取义不穷。已者止也。厉者不相援，而反相挤排，危厉之道也。</p><p>初九阳刚干体，志于必进。然当大畜之时，为六四所畜止，而不得自伸，故往则有危。惟止则不取祸矣，故教占者必利于止也。</p><h3 id="《象》曰-有厉利已-不犯灾也。" tabindex="-1">《象》曰：有厉利已，不犯灾也。 <a class="header-anchor" href="#《象》曰-有厉利已-不犯灾也。" aria-label="Permalink to “《象》曰：有厉利已，不犯灾也。”">​</a></h3><p>灾即厉也，止而不行，则不犯灾矣。</p><p>九二，舆说輹。(说音脱，輹音服。)</p><p>干错坤为舆，舆之象也。中爻兑为毁折，脱輹之象也。舆赖輹以行，脱则止而不行矣。</p><p>九二亦为六五所畜，以有中德，能自止而不进，故有舆说輹之象。占者凡事不冒进，斯无尤。</p><h3 id="《象》曰-舆说輹-中无尤也。" tabindex="-1">《象》曰：舆说輹，中无尤也。 <a class="header-anchor" href="#《象》曰-舆说輹-中无尤也。" aria-label="Permalink to “《象》曰：舆说輹，中无尤也。”">​</a></h3><p>惟有中德，故无妄进之尤。</p><p>九三，良马逐，利艰贞，曰闲舆卫，利有攸往。</p><p>此爻取蕴蓄之义。干为良马，之象之象也。中爻震，为作足之马，乾马在后追逐震马之象也。两马因震动而追逐，遇艮止不得驰上，利艰贞之象也。中爻兑口，干为言，曰之象也。干错坤，舆之象也。阴爻两列在前，卫之象也。《考工记》：“车有六等，戈也、人也、殳也、戟也、矛也、轸也，皆卫名。”良马逐者，用功如良马追逐之速也，即九三终日乾乾夕惕若之意。艰者，艰难其思虑，恐其失于太易也。贞者，贞固其作为，恐其失于助长也。曰者自叹之辞。闲者习也，习其车舆与其防卫也。闲习有优游自得之意。曰闲舆卫者，自叹其当闲与卫也，言当此大畜之时，为人所畜止摧抑，果何所事哉!亦惟自闲舆卫，以求往乎天衢耳。舆者任重之物，卫者应变之物。以人事论，君子不当家食，以一身而任天下之重者，舆也;当涉大川，以一身而应天下之变者，卫也。必多识前言往行之理，畜其刚健笃实之德，以德为车，以乐为御，忠信以为甲胄，仁义以为干橹，涵养于未用之时，以待时而动，此闲舆卫之意也。闲舆卫又利艰贞之象也，旧注以不相畜而俱进，殊不知卦名大畜，下体非自止，则蕴畜也，无进之意。盖观童牛之牿则知当有厉利已矣，观豮豕之牙则知当舆说輹矣，观何天之衢则知用功当良马逐矣。所以小象言上合志，所以当取蕴畜之义。唯蕴畜，方能畜极而通，何天之衢。</p><p>九三以阳居健极，当大畜之时，正多识前言往行，用功不已之时也，故有良马追逐之象。然犹恐其过刚锐进，惟当艰贞，从容以待时，故又有曰闲舆卫之象。如是自然畜极而通，利有攸往矣。故教戒占者，必当如此。</p><h3 id="《象》曰-利有攸往-上合志也。" tabindex="-1">《象》曰：利有攸往，上合志也。 <a class="header-anchor" href="#《象》曰-利有攸往-上合志也。" aria-label="Permalink to “《象》曰：利有攸往，上合志也。”">​</a></h3><p>上合志者，谓上九之志与之相合也，三与上九，情虽不相孚，然皆居二体之上，其志皆欲畜极而通，应与相合，所以利有攸往。</p><p>六四，童牛之梏*，元吉。</p><p>童者，未角之称。梏者施横木于牛角，以防其触，即《诗》所谓“楅衡”者也。此爻变离，离为牛，牛之象也。艮本少又应初，童牛之象也。变离错坎，梏之象也。艮手，中爻震木，手持木而施之角，亦梏之象也。</p><p>六四艮体居上，当畜干之时，与初相应，畜初者也。初以阳刚居卦之下，其势甚微，于此止之，为力甚易，故有梏童牛之象。占者如此，则止恶于未形，用力少而成功多，大善而吉之道也，故元吉。</p><ul><li>案：“梏”应作“牿”。</li></ul><h3 id="《象》曰-六四元吉-有喜也。" tabindex="-1">《象》曰：六四元吉，有喜也。 <a class="header-anchor" href="#《象》曰-六四元吉-有喜也。" aria-label="Permalink to “《象》曰：六四元吉，有喜也。”">​</a></h3><p>上不劳于禁制，下不伤于刑诛，故可喜。四正当兑口之悦，喜之象也。</p><p>六五，豮豕之牙，吉。(豮音焚)</p><p>本卦大象离，离错坎，豕之象也。五变中爻又成离矣。豮者犗也，腾也，乃走豕也，与童牛之梏一句同例。童字与豮字同，梏字与牙字同。中爻震足性动，豮之象也。牙者，《埤雅》云“以杙系豕也”，乃杙牙非齿牙也。《杜诗》“凫雏入桨牙”，《坡诗》“置酒看君中戟牙”，荆公“槎牙死树鸣老乌”，《阿房赋》“檐牙高啄”，又将军之旗曰牙，立于帐前，谓之牙帐。《考工记‧轮人》“牙也者所以为固抱也”，所以蜀人呼棹牙、凳牙、床牙，则牙字古今通用，非齿牙也。《诗》“椓之丁丁”，丁丁杙声也，以木入土，所以有声也。今船家系缆桩谓之灿，亦曰杙，牙者桩上权牙也。盖以丝系矢曰弋，故从弋，所以绳系木曰杙。变巽为绳，系之象也。巽木，杙之象也。言以绳系走豕于杙牙也。旧注，因宫刑或犗刑，遂以为去其势，但天下无啮人之豕，所以此豮字止有腾字意，无犗字意，牛马豕皆人之畜者，故大畜并言之。</p><p>六五以柔中居尊位，当畜干之时，畜乎其二者也，故有豮豕之牙之象，占者如此，则强暴梗化者，自屈服矣，故言。</p><h3 id="《象》曰-六五之吉-有庆也。" tabindex="-1">《象》曰：六五之吉，有庆也。 <a class="header-anchor" href="#《象》曰-六五之吉-有庆也。" aria-label="Permalink to “《象》曰：六五之吉，有庆也。”">​</a></h3><p>庆即喜，但五君位，所畜者大，故曰庆，即一人有庆也。</p><p>上九，何天之衢，亨。</p><p>此畜极而通之义。何，胡可切，音荷，儋也，负也。儋即担字，杨子儋石是也。《诗》“何蓑何笠”，皆音荷，《灵光赋》“荷天衢以元亨”，《庄子》“背负青天”，皆此意。郑康成亦言“肩荷”是也。上阳一画象担，二阴垂亸于两边，有担挑之象，言一担挑起天衢也，即陈白沙所谓“明月清风作两头，一挑挑到鲁尼丘”也。因卦体取此象，无此实事，金车玉铉之类是也。上为天位，天之象也。四达谓之衢，艮综震为大涂，衢之象也。以人事论，天衢乃朝廷政事之大道也。观《小象》曰“道大行”可知矣。</p><p>畜之既久，其道大行。正不家食，担任庙廊之重任。涉大川，担当国家之险阻，此其时矣，故有何天衢之象。占者得此，亨可知矣。</p><h3 id="《象》曰-何天之衢-道大行也。" tabindex="-1">《象》曰：何天之衢，道大行也。 <a class="header-anchor" href="#《象》曰-何天之衢-道大行也。" aria-label="Permalink to “《象》曰：何天之衢，道大行也。”">​</a></h3><p>道大行者，不家食，涉大川，无往而莫非亨也。道字即衢字。</p>',38)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
